let merchProducts=[];
function initializeMerch(){merchProducts=[
{id:'tee',name:P('The Heritage Tee','تيشيرت التراث'),price:30,desc:P('An ivory tee with a restrained burgundy chest print: Sudan, Meroë pyramids, and SSO UofA.','تيشيرت عاجي بطباعة عنابية بسيطة على الصدر تجمع السودان وأهرامات مروي واسم المنظمة.'),sizes:['XS','S','M','L','XL','2XL']},
{id:'hoodie',name:P('The Meroë Hoodie','هودي مروي'),price:65,desc:P('A deep burgundy hoodie with a cream heritage graphic on the back. From home to campus.','هودي عنابي برسمة تراثية كريمية على الظهر. من البيت إلى الجامعة.'),sizes:['XS','S','M','L','XL','2XL']},
{id:'tote',name:P('The Ahlan Tote','حقيبة أهلاً'),price:20,desc:P('Natural canvas, expressive “أهلاً بيك” lettering, and a flowing Nile-inspired detail.','قماش طبيعي وعبارة «أهلاً بيك» ولمسة مستوحاة من النيل.'),sizes:['One size']}];}
function merchPrice(n){return new Intl.NumberFormat(lang==='ar'?'ar-CA':'en-CA',{style:'currency',currency:'CAD',currencyDisplay:'code',maximumFractionDigits:0}).format(n)}
function merchSection(){if(!merchProducts.length)initializeMerch();return `<section class="section merch-section" id="merch" aria-labelledby="merch-title"><div class="sectiontop"><div><div class="eyebrow">${tr('Wear a little piece of home','خذ معك حتة من البيت')}</div><h2 id="merch-title">${tr('The SSO collection.','مجموعة المنظمة.')}</h2><p>${tr('Inspired by Sudan. Made for campus life.','مستوحاة من السودان ومن حياة الجامعة.')}</p></div><span class="merch-badge">${tr('COMING SOON','قريباً')}</span></div><p class="merch-disclaimer">${tr('Collection launching soon. Prices shown are estimates in CAD; final prices, sizing and pickup details will be announced before orders open.','المجموعة تُطلق قريباً. الأسعار تقديرية بالدولار الكندي؛ تُعلن الأسعار النهائية والمقاسات والاستلام قبل فتح الطلبات.')}</p><a class="button light cart-link" href="/sso-uofa/checkout.html">${tr('View bag & checkout','الحقيبة والدفع')} <span data-cart-count></span> </a><div class="merch-grid">${merchProducts.map(p=>`<article class="merch-card"><a class="merch-card-link" href="${productURL(p.id)}"><div class="merch-image"><img src="merch/${p.id}-studio.png" alt="${tr('Generated concept mockup:','معاينة تصميم مولدة:')} ${t(p.name)}" loading="lazy"><span class="merch-model-photo" aria-hidden="true" style="background-image:url('merch/${p.id}-gallery.png');background-position:${p.id==='hoodie'?'100% 0%':'0% 0%'}"></span></div><div class="merch-card-body"><div class="merch-card-title"><h3>${t(p.name)}</h3><span>${merchPrice(p.price)}</span></div><p>${t(p.desc)}</p><div class="merch-card-bottom"><small>${tr('Estimated price','سعر تقديري')}</small><span class="textlink">${tr('View product','عرض المنتج')}</span></div></div></a></article>`).join('')}</div><div class="merch-launch"><b>${tr('A small first drop.','إطلاق أول بسيط.')}</b><p>${tr('Watch for a limited pre-order window and campus pickup details. Orders are not open yet.','ترقّب فترة الطلب المسبق وتفاصيل الاستلام في الجامعة. لم تُفتح الطلبات بعد.')}</p></div></section>`}
